<?php require 'config.php';if(!empty($_SESSION['user_id']))go('user_dashboard.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['name'];go('user_dashboard.php');}$err='Invalid driver credentials.';}$page_title='Driver Login';require 'includes/header.php';?><div class="form-wrap"><div class="form-card"><span class="eyebrow">DRIVER ACCESS</span><h1>Welcome back.</h1><p>Sign in to your Parkora garage account.</p><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post"><div class="field"><label>Email</label><input type="email" name="email"  required></div><div class="field"><label>Password</label><input type="password" name="password" required></div><button class="btn primary" style="width:100%">Enter My Garage →</button></form><div class="card" style="margin-top:18px;background:#f5f0e9"><p style="text-align:center">New here? <a href="register.php">Create an account</a></p></div></div><?php require 'includes/footer.php';?>
